// one owning task per resource: exclusion by ordering, not by a lock object
class Serializer {
  #tail = Promise.resolve();
  run(task) {
    const result = this.#tail.then(task, task);
    this.#tail = result.catch(() => {});   // keep the chain alive after failure
    return result;
  }
}

